use vstd::prelude::*;

verus! {
    /// Given two vectors `a` and `b` of equal length, produce a vector of booleans
    /// indicating, at each index, whether `a[i] == b[i]`.
    fn equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
        requires
            a.len() == b.len(),
        ensures
            result.len() == a.len(),
            forall |i: usize| i < a.len() ==> result[i] == (a[i] == b[i]),
    {
        let mut result: Vec<bool> = Vec::new();
        let mut idx: usize = 0;
        // We iterate from idx = 0 up to idx = a.len(), pushing one boolean per iteration.
        while idx < a.len()
            invariant
                idx <= a.len(),
                result.len() == idx,
                forall |j: usize| j < idx ==> result[j] == (a[j] == b[j]),
            decreases
                a.len() - idx,
        {
            let ai = a[idx];
            let bi = b[idx];
            let eq = ai == bi;
            result.push(eq);
            idx += 1;
        }
        result
    }
}

